    {
      "name": "Archivist",
      "description": "Manages, preserves, and provides access to archival materials."
    },
    {
      "name": "File",
      "description": "Digital item in the archive containing content and metadata.",
      "attributes": [
        "Publication",
        "Share Data",
        "Copyright Status",
        "Restriction End Date",
        "Metadata"
      ]
    },
    {
      "name": "Publication",
      "description": "Published work referencing archival materials."
    },
    {
      "name": "Share Data",
