    },
    {
      "name": "Restriction End Date",
      "description": "Date when a restricted file becomes public."
    },
    {
      "name": "License",
      "description": "Defines how a file may be used or shared."
    },
    {
      "name": "Access Copy",
      "description": "Lower-resolution version of a file for public access."
    },
    {
      "name": "Metadata",
